// stores/store.js
import { createStore } from "vuex";
import axios from "axios";

const store = createStore({
  state: {
    user: null, // 存储用户信息
  },
  mutations: {
    setUser(state, user) {
      state.user = user; // 设置用户信息
      // 同时将整个用户对象存储到 localStorage
      localStorage.setItem('user', JSON.stringify(user)); // 存储时将对象转换为 JSON 字符串
    },
    clearUser(state) {
      state.user = {}; // 清空用户信息
      localStorage.removeItem('user'); // 移除 localStorage 中的用户信息
    }
  },
  actions: {
    async login({ commit }, credentials) {
      try {
        const response = await axios.post(
          "http://localhost:5000/api/auth/login",
          credentials,
        );
        const data = response.data.data; // 获取正确的数据格式
        // 提取用户信息和 token 数据
        if (data.user) {
          commit("setUser", data.user); // 存储用户信息
          return data; // 返回数据以便于在组件中使用
        }
      } catch (error) {
        console.error("登录请求失败", error);
        throw new Error("登录请求失败"); // 可以在组件中捕获并处理
      }
    },
  },
  getters: {
    user: (state) => {
      // 确保在获取用户时，从 localStorage 中恢复数据
      return state.user || JSON.parse(localStorage.getItem('user')) || {};
    },

    userId(state) {
      return state.user ? state.user.id : null; // 获取用户 ID
    },
    userNickname(state) {
      return state.user ? state.user.nickname : "用户"; // 获取用户昵称
    },
  },
});

export default store;
